class TreeAncestor {
    private int[][] up;
    private static final int LOG = 16;

    public TreeAncestor(int n, int[] parent) {
        up = new int[n][LOG];
        for (int i = 0; i < n; i++) {
            Arrays.fill(up[i], -1);
            up[i][0] = parent[i];
        }
        for (int j = 1; j < LOG; j++) {
            for (int i = 0; i < n; i++) {
                if (up[i][j - 1] != -1) {
                    up[i][j] = up[up[i][j - 1]][j - 1];
                }
            }
        }
    }

    public int getKthAncestor(int node, int k) {
        for (int j = 0; j < LOG; j++) {
            if (((k >> j) & 1) == 1) {
                node = up[node][j];
                if (node == -1) break;
            }
        }
        return node;
    }
}

var TreeAncestor = function(n, parent) {
    const LOG = 16;
    this.up = Array.from({ length: n }, () => Array(LOG).fill(-1));
    for (let i = 0; i < n; i++) {
        this.up[i][0] = parent[i];
    }
    for (let j = 1; j < LOG; j++) {
        for (let i = 0; i < n; i++) {
            if (this.up[i][j - 1] !== -1) {
                this.up[i][j] = this.up[this.up[i][j - 1]][j - 1];
            }
        }
    }
};

TreeAncestor.prototype.getKthAncestor = function(node, k) {
    const LOG = 16;
    for (let j = 0; j < LOG; j++) {
        if ((k >> j) & 1) {
            node = this.up[node][j];
            if (node === -1) break;
        }
    }
    return node;
